"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["72452"],{49057(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>c,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>h});var a=JSON.parse('{"id":"qiangguo/abstracthumanity","title":"","description":"[\u4E7E\u5764\u4E00\u5F20\u7EB8\uFF0C\u4E00\u5B57\u4E00\u661F\u8FB0] posted on 2003-07-22 2130","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/abstracthumanity.md","sourceDirName":"qiangguo","slug":"/qiangguo/abstracthumanity","permalink":"/en/qiangguo/abstracthumanity","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"abstracthumanity","title":"","hide_table_of_contents":true,"sidebar_label":"Proving That Abstract Human Nature Does Not Exist"},"sidebar":"qiangguoSidebar","previous":{"title":"Class Struggle Handbook 2: How Did \\"Class Struggle\\" Become the Left\'s Underwear!","permalink":"/en/qiangguo/classstrugglemanual"},"next":{"title":"\u751F\u6B96\u5668\u3001\u4E0A\u5E1D\u3001\u795E\u4E0E\u5076\u50CF\uFF0C\u8C08\u8C08\u4EBA\u7C7B\u5D07\u62DC\u7684\u6A21\u5F0F","permalink":"/en/qiangguo/worshippattern"}}'),i=n(74848),o=n(28453);let s={id:"abstracthumanity",title:"",hide_table_of_contents:!0,sidebar_label:"Proving That Abstract Human Nature Does Not Exist"},r="A Proof That Abstract Human Nature Does Not Exist",h={},l=[];function u(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"a-proof-that-abstract-human-nature-does-not-exist",children:"A Proof That Abstract Human Nature Does Not Exist"})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"[\u4E7E\u5764\u4E00\u5F20\u7EB8\uFF0C\u4E00\u5B57\u4E00\u661F\u8FB0] posted on 2003-07-22 21:44:30"}),"\n"]}),"\n",(0,i.jsxs)(t.p,{children:["--------------------------------------------------------------------------------",(0,i.jsx)("br",{})]}),"\n",(0,i.jsx)(t.p,{children:'"At birth, human nature is inherently good"\u2014or swap a word, "inherently evil," or "a mix of good and evil," and so on. There are many possible formulations, but in reality they are all nonsensical drivel. All sermons about so-called human nature must first have a premise: the existence of said human nature. So, does human nature exist?'}),"\n",(0,i.jsx)(t.p,{children:'So-called human nature, according to those who believe in it, refers to qualities that every person in reality possesses. Here lies a problem: what is a "person"? If you believe that humans evolved, then the definition of "person" has a temporal dimension, and all definitions become helpless in the face of time. Even if you broaden "person" to "living being," the above discussion still holds. The only way to salvage this is to assume that what makes a person a person is some quality that determines their personhood, a quality that does not change with time, and then define this quality as "human nature." If so, one faces two choices: 1. There is no such thing as evolution\u2014for example, believing in God\'s creation of man or in reincarnation dependent on the soul. 2. Evolution exists, but since this quality is assumed to be time-independent and unchanging, and from an evolutionary perspective one must trace back to atoms or even further, human nature derives from the nature of matter and is identical to it. In that case, everything would be "human." Therefore, under the premise of evolution, a human nature distinct from the nature of matter does not exist. In summary, once we assume this unchanging human nature exists, we face two choices: 1. God\'s creation of man or reincarnation dependent on the soul (it must be noted here that Buddhism does not acknowledge this kind of reincarnation dependent on the soul; this scenario has nothing to do with Buddhism. Therefore, this case can be more simply stated as: acknowledging the existence of an immortal soul). 2. A human nature identical to the nature of matter.'}),"\n",(0,i.jsx)(t.p,{children:"For the first case, human nature or its vessel is the immortal soul. Since it must be distinguished from the second case, this thing cannot be material. Then there are two sub-cases: 1. This thing intervenes in our everyday reality. 2. This thing does not intervene in our everyday reality. For sub-case 1, this thing's intervention cannot possibly produce identical corresponding effects on every person. Because if it produced identical corresponding effects on every person, then all people in the same situation should have similar reactions, which clearly contradicts reality. Therefore, even if this thing exists, it either does not intervene in our everyday reality, or even if it does, it would not produce identical corresponding effects on every person. In other words, this thing cannot in reality serve as a common premise meaningful to all people. And since believers in so-called human nature define it as qualities that every person in reality possesses, this immortal soul, even if it exists, has nothing to do with human nature."}),"\n",(0,i.jsx)(t.p,{children:"For the second case, human nature is identical to the nature of matter. Therefore, all human behavior relates to some physical property, and all people in the same situation should also have similar reactions. But this clearly contradicts reality\u2014human behavior cannot be entirely and unconditionally reduced to purely material influences like physics and chemistry. This means the second case also does not hold."}),"\n",(0,i.jsx)(t.p,{children:"Summarizing the above analysis: the kind of human nature that believers in so-called human nature refer to\u2014qualities that every person in reality possesses\u2014does not exist. It is all nonsense. Therefore, our only choice is: to acknowledge that in reality there is no human nature that applies to everyone, meaning that human nature is related to history, to society, to class, and so on. Only in this sense can we meaningfully discuss so-called human nature."})]})}function c(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(96540);let i={},o=a.createContext(i);function s(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);